const input = $json;
const html = input.html;

if (typeof html !== 'string' || html.length === 0) {
  throw new Error('[Создать HTML artifact] REPORT_HTML_INVALID: html is empty');
}

const filename = input.filename;
if (typeof filename !== 'string' || !/\.html$/i.test(filename)) {
  throw new Error('[Создать HTML artifact] REPORT_HTML_FILENAME_INVALID');
}

if (input.mime_type !== 'text/html') {
  throw new Error('[Создать HTML artifact] REPORT_HTML_INVALID: mime_type');
}

const data = Buffer.from(html, 'utf8').toString('base64');
const decodedHtml = Buffer.from(data, 'base64').toString('utf8');
const sizeBytes = Buffer.byteLength(html, 'utf8');

if (sizeBytes <= 0 || decodedHtml !== html) {
  throw new Error('[Создать HTML artifact] REPORT_HTML_INVALID: binary round-trip');
}

return [
  {
    json: {
      analysis_run_id: input.analysis_run_id,
      filename,
      mime_type: 'text/html',
      template_version: input.template_version,
      expected_field_count: input.expected_field_count,
      artifact_validation: {
        valid: true,
        property: 'report_html',
        size_bytes: sizeBytes,
        html_matches_renderer: true,
      },
    },
    binary: {
      report_html: {
        data,
        mimeType: 'text/html',
        fileName: filename,
      },
    },
  },
];

const items = $input.all();
if (items.length !== 1) {
  throw new Error('[TEST Report Replay] REPORT_REPLAY_CONTRACT_INVALID: expected one item');
}
const input = items[0].json;
if (!input.analysis_run_id || input.analysis_run_id !== '3caa7a89-b137-4cf6-b23d-941fb465c8f9') {
  throw new Error('[TEST Report Replay] REPORT_REPLAY_CONTRACT_INVALID: analysis_run_id');
}
if (input.report_replay_authorized !== true) {
  throw new Error('[TEST Report Replay] REPORT_REPLAY_NOT_AUTHORIZED');
}
if (input.completion_claimed !== false) {
  throw new Error('[TEST Report Replay] REPORT_REPLAY_CONTRACT_INVALID: completion_claimed must remain false');
}
if (input.finalization_state !== 'already_completed' || input.run_status !== 'completed') {
  throw new Error('[TEST Report Replay] REPORT_REPLAY_CONTRACT_INVALID: truthful lifecycle state required');
}
if (
  input.barrier_ready !== true ||
  input.final_count !== 27 ||
  input.valid_status_count !== 27 ||
  input.valid_catalog_count !== 27 ||
  input.valid_contract_count !== 27 ||
  !Array.isArray(input.missing_keys) || input.missing_keys.length !== 0 ||
  !Array.isArray(input.unexpected_keys) || input.unexpected_keys.length !== 0
) {
  throw new Error('[TEST Report Replay] REPORT_REPLAY_BARRIER_INVALID: exact 27/27 proof required');
}
if (
  input.runner_contract_version !== 'tender_aggregator_e2e_pin_runner_v1' ||
  input.report_policy_version !== 'one_report_per_runner_execution_v1' ||
  input.source_workflow_id !== 'ftvmrEHoMbPOAqZG' ||
  input.source_workflow_version_id !== '91c17313-a593-4fb9-9072-79320a958dd7' ||
  input.production_report_workflow_id !== 'ckPnP3hRhKu4Mf9u' ||
  input.production_report_version_id !== '9d095af6-b60d-4ad9-8061-432201ec0e8e' ||
  input.report_dispatch_owner !== 'test_controller_replay'
) {
  throw new Error('[TEST Report Replay] REPORT_REPLAY_AUDIT_INVALID');
}

return [{
  json: {
    analysis_run_id: input.analysis_run_id,
    final_count: input.final_count,
