const snapshot = $json.report_snapshot;

const EXPECTED_SNAPSHOT_VERSION = 'tender_report_snapshot_v2';
const EXPECTED_FIELD_CONTRACT_KEYS = [
  'field_index',
  'field_key',
  'status',
  'value_text',
  'confidence',
  'requires_human_review',
  'result_json',
];
const EXPECTED_FIELDS = [
  [1, 'procurement_subject'],
  [2, 'nm_price_with_vat'],
  [3, 'platform'],
  [4, 'procedure_type'],
  [5, 'application_deadline'],
  [6, 'application_review_date'],
  [7, 'results_date'],
  [8, 'customer'],
  [9, 'customer_contacts'],
  [10, 'participation_cost'],
  [11, 'participation_guarantee'],
  [12, 'evaluation_criteria'],
  [13, 'delivery_term'],
  [14, 'payment_terms'],
  [15, 'special_account_or_treasury'],
  [16, 'bank_support'],
  [17, 'government_contract'],
  [18, 'rebidding'],
  [19, 'national_regime'],
  [20, 'advance_contract_guarantee'],
  [21, 'warranty_obligations_guarantee'],
  [22, 'licenses_certificates'],
  [23, 'required_official_certificates'],
  [24, 'similar_supply_experience'],
  [25, 'analog_allowed'],
  [26, 'analog_definition'],
  [27, 'application_documents'],
];

if (!snapshot || typeof snapshot !== 'object' || Array.isArray(snapshot)) {
  throw new Error('[Проверить Report Snapshot] REPORT_SNAPSHOT_SHAPE_INVALID: нет объекта report_snapshot');
}

if (snapshot.snapshot_version !== EXPECTED_SNAPSHOT_VERSION) {
  throw new Error(
    `[Проверить Report Snapshot] REPORT_SNAPSHOT_SHAPE_INVALID: snapshot_version=${snapshot.snapshot_version ?? 'null'}`
  );
}

if (!snapshot.analysis_run || typeof snapshot.analysis_run !== 'object' || Array.isArray(snapshot.analysis_run)) {
  throw new Error('[Проверить Report Snapshot] REPORT_RUN_NOT_COMPLETED: analysis_run отсутствует');
}

if (snapshot.analysis_run.status !== 'completed') {
  throw new Error(
    `[Проверить Report Snapshot] REPORT_RUN_NOT_COMPLETED: status=${snapshot.analysis_run.status ?? 'null'}`
  );
}

if (!Array.isArray(snapshot.field_results)) {
  throw new Error('[Проверить Report Snapshot] REPORT_SNAPSHOT_FIELD_COUNT_INVALID: field_results не массив');
}

if (snapshot.field_results.length !== EXPECTED_FIELDS.length) {
  throw new Error(
    `[Проверить Report Snapshot] REPORT_SNAPSHOT_FIELD_COUNT_INVALID: получено ${snapshot.field_results.length}, ожидалось ${EXPECTED_FIELDS.length}`
  );
}

for (let index = 0; index < EXPECTED_FIELDS.length; index += 1) {
  const [expectedIndex, expectedKey] = EXPECTED_FIELDS[index];
  const field = snapshot.field_results[index];

  if (!field || field.field_index !== expectedIndex || field.field_key !== expectedKey) {
    throw new Error(
      `[Проверить Report Snapshot] REPORT_ANALYSIS_CONTRACT_CHANGED: ожидалось ${expectedIndex}/${expectedKey}, получено ${field?.field_index ?? 'null'}/${field?.field_key ?? 'null'}`
    );
  }

  const actualKeys = Object.keys(field).sort();
  const expectedKeys = [...EXPECTED_FIELD_CONTRACT_KEYS].sort();
  if (actualKeys.length !== expectedKeys.length || actualKeys.some((key, keyIndex) => key !== expectedKeys[keyIndex])) {
    throw new Error(
      `[Проверить Report Snapshot] REPORT_ANALYSIS_CONTRACT_CHANGED: ${expectedKey} не содержит exact seven-field contract`
    );
  }

  if (!['resolved', 'requires_review', 'not_found'].includes(field.status)) {
    throw new Error(
      `[Проверить Report Snapshot] REPORT_ANALYSIS_CONTRACT_CHANGED: недопустимый status для ${expectedKey}`
    );
  }

  const confidenceIsValid = field.confidence === null || (
    typeof field.confidence === 'number'
    && Number.isFinite(field.confidence)
    && field.confidence >= 0
    && field.confidence <= 1
  );

  if (!confidenceIsValid || typeof field.requires_human_review !== 'boolean') {
    throw new Error(
      `[Проверить Report Snapshot] REPORT_ANALYSIS_CONTRACT_CHANGED: confidence/requires_human_review для ${expectedKey}`
    );
  }

  if (field.status === 'resolved' && (
    typeof field.value_text !== 'string'
    || !field.value_text.trim()
    || field.confidence === null
    || field.requires_human_review !== false
  )) {
    throw new Error(
      `[Проверить Report Snapshot] REPORT_ANALYSIS_CONTRACT_CHANGED: resolved invariant для ${expectedKey}`
    );
  }

  if (field.status === 'requires_review' && field.requires_human_review !== true) {
    throw new Error(
      `[Проверить Report Snapshot] REPORT_ANALYSIS_CONTRACT_CHANGED: requires_review invariant для ${expectedKey}`
    );
  }

  if (field.status === 'not_found' && (
    field.value_text !== null
    || field.confidence !== null
    || field.requires_human_review !== false
  )) {
    throw new Error(
      `[Проверить Report Snapshot] REPORT_ANALYSIS_CONTRACT_CHANGED: not_found invariant для ${expectedKey}`
    );
  }
}

const sourceIndex = snapshot.source_index;
if (!sourceIndex || typeof sourceIndex !== 'object' || Array.isArray(sourceIndex)
  || !Array.isArray(sourceIndex.documents)
  || !Array.isArray(sourceIndex.facts)
  || !Array.isArray(sourceIndex.units)) {
  throw new Error('[Проверить Report Snapshot] REPORT_SNAPSHOT_SOURCE_INDEX_INVALID');
}

return [
