    json: {
      report_snapshot: {
        ...snapshot,
        snapshot_validation: {
          valid: true,
          field_count: snapshot.field_results.length,
          indexes_valid: true,
          keys_valid: true,
          contract_valid: true,
        },
      },
    },
  },
];

