}

if (!Array.isArray(snapshot.field_results) || !snapshot.source_index) {
  throw new Error('[Адаптировать поля отчёта] REPORT_SNAPSHOT_SHAPE_INVALID');
}

function asArray(value) {
  return Array.isArray(value) ? value : [];
}

function asLookup(items, key) {
  const lookup = new Map();
  for (const item of asArray(items)) {
    const value = item?.[key];
    if (value === null || value === undefined) continue;
    const normalized = String(value);
    const matches = lookup.get(normalized) ?? [];
    matches.push(item);
    lookup.set(normalized, matches);
  }
  return lookup;
}

function documentName(document) {
  if (typeof document === 'string' && document.trim()) return document;
  if (!document || typeof document !== 'object') return null;
  return document.file_name ?? document.display_name ?? document.name ?? null;
}

function nullable(value) {
  return value === undefined || value === '' ? null : value;
}

function findSemanticBlockMatches(value, semanticBlockId, matches, visited = new Set()) {
  if (!value || typeof value !== 'object' || visited.has(value)) return;
  visited.add(value);
  if (value.semantic_block_id === semanticBlockId) matches.add(true);
  for (const nested of Object.values(value)) {
    findSemanticBlockMatches(nested, semanticBlockId, matches, visited);
  }
}

const documentsById = asLookup(snapshot.source_index.documents, 'document_id');
const factsById = asLookup(snapshot.source_index.facts, 'fact_id');
const unitsByAnalysisUnitId = asLookup(snapshot.source_index.units, 'analysis_unit_id');

function resolveUnitBySemanticBlock(semanticBlockId) {
  const matches = [];
  for (const unit of asArray(snapshot.source_index.units)) {
    const found = new Set();
    findSemanticBlockMatches(unit.ai_segments, semanticBlockId, found);
    findSemanticBlockMatches(unit.provenance, semanticBlockId, found);
    if (found.size > 0) matches.push(unit);
  }
  return matches;
}

function locationFromEvidence(evidence, unit) {
  const pages = asArray(unit?.source_pages).filter(page => page !== null && page !== undefined);
  return {
    page: nullable(evidence.page_from ?? pages[0]),
    page_to: nullable(evidence.page_to ?? pages[pages.length - 1]),
    sheet: nullable(evidence.sheet_name ?? evidence.sheet),
    quote: nullable(evidence.quote ?? evidence.text),
  };
}

function sourceFromEvidence(evidence, field, diagnostics) {
  if (evidence?.source_type === 'tender_metadata') {
    return {
      source: {
        kind: 'tender_metadata',
        document: 'TenderPlan — карточка закупки',
        page: null,
        page_to: null,
        sheet: null,
        quote: null,
        location_status: 'not_applicable',
      },
      metadata: true,
      documentResolved: false,
    };
  }

  const diagnosticStart = diagnostics.length;
  const embeddedDocument = documentName(evidence?.document);
  const candidateRef = typeof evidence?.candidate_ref === 'string' ? evidence.candidate_ref : null;
  const referencedFactId = candidateRef?.startsWith('fact:')
    ? candidateRef.slice('fact:'.length)
    : (typeof evidence?.fact_id === 'string' ? evidence.fact_id : null);

  let fact = null;
  let unit = null;
  let resolvedDocument = embeddedDocument;

  if (referencedFactId) {
    const factMatches = factsById.get(referencedFactId) ?? [];
    if (factMatches.length !== 1) {
      diagnostics.push({
        field_index: field.field_index,
        field_key: field.field_key,
        reason: factMatches.length === 0 ? 'fact_reference_not_found' : 'fact_reference_ambiguous',
      });
    } else {
      fact = factMatches[0];
      const factDocumentMatches = documentsById.get(String(fact.document_id)) ?? [];
      if (!resolvedDocument && factDocumentMatches.length === 1) {
        resolvedDocument = documentName(factDocumentMatches[0]);
      }
      if (factDocumentMatches.length > 1) {
        diagnostics.push({ field_index: field.field_index, field_key: field.field_key, reason: 'fact_document_ambiguous' });
      }
      const factUnitMatches = unitsByAnalysisUnitId.get(String(fact.analysis_unit_id)) ?? [];
      if (factUnitMatches.length === 1) unit = factUnitMatches[0];
    }
  }

  if (!unit && typeof evidence?.analysis_unit_id === 'string') {
    const unitMatches = unitsByAnalysisUnitId.get(evidence.analysis_unit_id) ?? [];
    if (unitMatches.length === 1) {
      unit = unitMatches[0];
    } else {
      diagnostics.push({
        field_index: field.field_index,
        field_key: field.field_key,
        reason: unitMatches.length === 0 ? 'analysis_unit_not_found' : 'analysis_unit_ambiguous',
      });
    }
  }

  if (!unit && typeof evidence?.semantic_block_id === 'string') {
    const semanticMatches = resolveUnitBySemanticBlock(evidence.semantic_block_id);
    if (semanticMatches.length === 1) {
      unit = semanticMatches[0];
    } else if (!referencedFactId) {
      diagnostics.push({
        field_index: field.field_index,
        field_key: field.field_key,
        reason: semanticMatches.length === 0 ? 'semantic_block_not_found' : 'semantic_block_ambiguous',
      });
    }
  }

  if (!resolvedDocument && unit) {
    const unitDocumentMatches = documentsById.get(String(unit.document_id)) ?? [];
    if (unitDocumentMatches.length === 1) {
      resolvedDocument = documentName(unitDocumentMatches[0]);
    } else if (unitDocumentMatches.length > 1) {
      diagnostics.push({ field_index: field.field_index, field_key: field.field_key, reason: 'unit_document_ambiguous' });
    }
  }

  if (!resolvedDocument && !referencedFactId && !unit && !embeddedDocument) {
    diagnostics.push({ field_index: field.field_index, field_key: field.field_key, reason: 'source_reference_missing' });
  } else if (!resolvedDocument && referencedFactId) {
    diagnostics.push({ field_index: field.field_index, field_key: field.field_key, reason: 'document_name_unresolved' });
  }

  const location = locationFromEvidence(evidence ?? {}, unit);
  const hasAmbiguousLocation = diagnostics
    .slice(diagnosticStart)
    .some(diagnostic => diagnostic.reason.endsWith('_ambiguous'));

  return {
    source: {
      kind: 'document',
      document: resolvedDocument ?? null,
      ...location,
      location_status: resolvedDocument
        ? (location.page !== null || location.sheet !== null ? 'exact' : 'unavailable')
        : (hasAmbiguousLocation ? 'ambiguous' : 'unavailable'),
    },
    metadata: false,
    documentResolved: Boolean(resolvedDocument),
  };
}

const unresolvedSourceReferences = [];
const metrics = {
  evidence_processed: 0,
  document_sources_resolved: 0,
  metadata_sources: 0,
};

function statusText(status) {
  switch (status) {
    case 'resolved':
      return 'Подтверждено';
    case 'requires_review':
      return 'Требует проверки';
    case 'not_found':
      return 'Не найдено';
    default:
      throw new Error(`[Адаптировать поля отчёта] REPORT_ANALYSIS_CONTRACT_MUTATED: status=${status}`);
  }
}

const adaptedFields = snapshot.field_results.map(field => {
  const presentation = PRESENTATION[field.field_key];
  if (!presentation) {
    throw new Error(`[Адаптировать поля отчёта] REPORT_FIELD_MAPPING_INCOMPLETE: ${field.field_key}`);
  }

  const analysisResult = { ...field };
  const evidence = field.status === 'not_found'
    ? []
    : asArray(field.result_json?.evidence);
  const sources = [];
  const sourceKeys = new Set();

  for (const item of evidence) {
    metrics.evidence_processed += 1;
    const resolved = sourceFromEvidence(item, field, unresolvedSourceReferences);
    if (resolved.metadata) metrics.metadata_sources += 1;
    if (resolved.documentResolved) metrics.document_sources_resolved += 1;

    const sourceKey = JSON.stringify(resolved.source);
    if (!sourceKeys.has(sourceKey)) {
      sourceKeys.add(sourceKey);
      sources.push(resolved.source);
    }
  }

  return {
    analysis_result: analysisResult,
    presentation: {
      client_field_name: presentation.title,
      section_name: presentation.section,
      status_text: statusText(field.status),
    },
    sources,
  };
});

return [
  {
    json: {
      adapter_version: 'tender_report_adapter_v2',
      analysis_run_id: snapshot.analysis_run_id,
      analysis_run: snapshot.analysis_run,
      adapted_fields: adaptedFields,
      adapter_diagnostics: {
        ...metrics,
        unresolved_source_references: unresolvedSourceReferences,
      },
    },
  },
];

const input = $json;

if (input.adapter_version !== 'tender_report_adapter_v2') {
  throw new Error('[Собрать Report Model] REPORT_MODEL_INVALID: adapter_version');
}

if (!input.analysis_run_id || !input.analysis_run || typeof input.analysis_run !== 'object') {
  throw new Error('[Собрать Report Model] REPORT_MODEL_INVALID: analysis_run');
}

if (!Array.isArray(input.adapted_fields)) {
  throw new Error('[Собрать Report Model] REPORT_MODEL_INVALID: adapted_fields');
}

// Metadata is presentation-only. Invalid or missing metadata is represented by null,
// never by substituting a canonical FINAL result.
const tenderMeta = input.analysis_run.tender_meta
  && typeof input.analysis_run.tender_meta === 'object'
  && !Array.isArray(input.analysis_run.tender_meta)
  ? input.analysis_run.tender_meta
  : {};

const customer = tenderMeta.primary_customer?.name
  ?? tenderMeta.customers?.[0]?.name
  ?? null;

const procurement = {
  number: tenderMeta.tender_number ?? null,
  subject: tenderMeta.title ?? null,
  customer,
  platform: tenderMeta.platform?.name ?? null,
  price: tenderMeta.max_price ?? null,
  publication_at: tenderMeta.publication_at ?? null,
};

const statistics = {
  total: input.adapted_fields.length,
  resolved: 0,
  requires_review: 0,
  not_found: 0,
};

for (const field of input.adapted_fields) {
  const status = field?.analysis_result?.status;
  if (!Object.hasOwn(statistics, status)) {
    throw new Error(
      `[Собрать Report Model] REPORT_MODEL_INVALID: status=${status ?? 'null'}`
    );
  }
  statistics[status] += 1;
}

// Preserve the adapted objects themselves. Report Model does not normalize
// canonical analysis_result, presentation, or sources.
const fields = input.adapted_fields;

const attentionFieldIndexes = fields
  .filter(field => field.analysis_result.requires_human_review === true)
  .map(field => field.analysis_result.field_index);

return [
  {
    json: {
      report_model_version: 'tender_report_model_v2',
      internal: {
        analysis_run_id: input.analysis_run_id,
        snapshot_version: 'tender_report_snapshot_v2',
      },
      procurement,
      statistics,
      fields,
      attention_field_indexes: attentionFieldIndexes,
    },
  },
];

const model = $json;

const EXPECTED_FIELDS = [
  [1, 'procurement_subject'],
  [2, 'nm_price_with_vat'],
  [3, 'platform'],
  [4, 'procedure_type'],
  [5, 'application_deadline'],
  [6, 'application_review_date'],
