  [23, 'required_official_certificates'],
  [24, 'similar_supply_experience'],
  [25, 'analog_allowed'],
  [26, 'analog_definition'],
  [27, 'application_documents'],
];
const CANONICAL_KEYS = [
  'field_index',
  'field_key',
  'status',
  'value_text',
  'confidence',
  'requires_human_review',
  'result_json',
].sort();
const PRESENTATION_KEYS = [
  'client_field_name',
  'section_name',
  'status_text',
].sort();
const SOURCE_KEYS = [
  'kind',
  'document',
  'page',
  'page_to',
  'sheet',
  'quote',
  'location_status',
].sort();

function hasExactKeys(value, expectedKeys) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return false;
  const actualKeys = Object.keys(value).sort();
  return actualKeys.length === expectedKeys.length
    && actualKeys.every((key, index) => key === expectedKeys[index]);
}

function expectedStatusText(status) {
  switch (status) {
    case 'resolved':
      return 'Подтверждено';
    case 'requires_review':
      return 'Требует проверки';
    case 'not_found':
      return 'Не найдено';
    default:
      return null;
  }
}

if (model.report_model_version !== 'tender_report_model_v2') {
  throw new Error('[Проверить Report Model] REPORT_MODEL_INVALID: report_model_version');
}

if (!model.internal || !model.internal.analysis_run_id) {
  throw new Error('[Проверить Report Model] REPORT_MODEL_INVALID: internal');
}

if (!model.procurement || typeof model.procurement !== 'object' || Array.isArray(model.procurement)) {
  throw new Error('[Проверить Report Model] REPORT_MODEL_INVALID: procurement');
}

if (!Array.isArray(model.fields) || model.fields.length !== EXPECTED_FIELDS.length) {
  throw new Error(
    `[Проверить Report Model] REPORT_MODEL_INVALID: fields=${model.fields?.length ?? 'null'}`
  );
}

const recomputedStatistics = {
  total: model.fields.length,
  resolved: 0,
  requires_review: 0,
  not_found: 0,
};
const expectedAttentionIndexes = [];

for (let index = 0; index < EXPECTED_FIELDS.length; index += 1) {
