    || analysisResult.field_key !== expectedKey) {
    throw new Error(
      `[Проверить Report Model] REPORT_MODEL_ORDER_INVALID: expected ${expectedIndex}/${expectedKey}`
    );
  }

  if (!hasExactKeys(analysisResult, CANONICAL_KEYS)) {
    throw new Error(
      `[Проверить Report Model] REPORT_MODEL_INVALID: canonical contract for ${expectedKey}`
    );
  }

  if (!Object.hasOwn(recomputedStatistics, analysisResult.status)) {
    throw new Error(
      `[Проверить Report Model] REPORT_MODEL_INVALID: status for ${expectedKey}`
    );
  }
  recomputedStatistics[analysisResult.status] += 1;

  if (!hasExactKeys(field.presentation, PRESENTATION_KEYS)
    || field.presentation.status_text !== expectedStatusText(analysisResult.status)) {
    throw new Error(
      `[Проверить Report Model] REPORT_MODEL_INVALID: presentation for ${expectedKey}`
    );
  }

  if (!Array.isArray(field.sources)) {
    throw new Error(
      `[Проверить Report Model] REPORT_MODEL_INVALID: sources for ${expectedKey}`
    );
  }

  if (analysisResult.status === 'not_found' && field.sources.length !== 0) {
    throw new Error(
      `[Проверить Report Model] REPORT_MODEL_INVALID: not_found sources for ${expectedKey}`
    );
  }

  for (const source of field.sources) {
    if (!hasExactKeys(source, SOURCE_KEYS)) {
      throw new Error(
        `[Проверить Report Model] REPORT_MODEL_INVALID: source contract for ${expectedKey}`
      );
    }
  }

  if (analysisResult.requires_human_review === true) {
    expectedAttentionIndexes.push(analysisResult.field_index);
  }
}

if (!model.statistics
  || model.statistics.total !== recomputedStatistics.total
  || model.statistics.resolved !== recomputedStatistics.resolved
  || model.statistics.requires_review !== recomputedStatistics.requires_review
  || model.statistics.not_found !== recomputedStatistics.not_found) {
  throw new Error('[Проверить Report Model] REPORT_MODEL_STATISTICS_INVALID');
}

if (!Array.isArray(model.attention_field_indexes)
  || JSON.stringify(model.attention_field_indexes) !== JSON.stringify(expectedAttentionIndexes)) {
  throw new Error('[Проверить Report Model] REPORT_MODEL_INVALID: attention_field_indexes');
}

return [
