function escapeHtml(value) {
  if (value === null || value === undefined) return '';
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function formatDate(value) {
  if (value === null || value === undefined || value === '') return 'Не указана';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return escapeHtml(value);
  return new Intl.DateTimeFormat('ru-RU', {
    timeZone: 'Europe/Moscow',
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
  }).format(date);
}

function formatPrice(value) {
  if (value === null || value === undefined || value === '') return 'Не указана';
  const numericValue = Number(value);
  return Number.isFinite(numericValue)
    ? `${new Intl.NumberFormat('ru-RU').format(numericValue)} ₽`
    : escapeHtml(value);
}

function statusClass(status) {
  return {
    resolved: 'status-resolved',
    requires_review: 'status-review',
    not_found: 'status-not-found',
  }[status] ?? 'status-unknown';
}

function renderSource(source) {
  if (source.kind === 'tender_metadata') {
    return `<li class="source source-metadata"><strong>Данные площадки:</strong> ${escapeHtml(source.document)}</li>`;
  }

  const locations = [];
  if (source.page !== null && source.page !== undefined) {
    const pageTo = source.page_to !== null && source.page_to !== undefined
      && source.page_to !== source.page
      ? `–${escapeHtml(source.page_to)}`
      : '';
    locations.push(`стр. ${escapeHtml(source.page)}${pageTo}`);
  }
  if (source.sheet !== null && source.sheet !== undefined && source.sheet !== '') {
    locations.push(`лист ${escapeHtml(source.sheet)}`);
  }

  const location = locations.length > 0
    ? ` <span class="source-location">(${locations.join(', ')})</span>`
    : '';
  const quote = source.quote === null || source.quote === undefined || source.quote === ''
    ? ''
    : `<blockquote>${escapeHtml(source.quote)}</blockquote>`;

  return `<li class="source"><strong>${escapeHtml(source.document)}</strong>${location}${quote}</li>`;
}

function renderFieldRow(field) {
  const { analysis_result: analysisResult, presentation, sources } = field;
  const value = analysisResult.status === 'not_found'
    ? NOT_FOUND_TEXT
    : (analysisResult.value_text ?? 'Требует проверки');
  const sourceHtml = sources.length > 0
    ? `<ul class="sources">${sources.map(renderSource).join('')}</ul>`
    : '<span class="source-empty">—</span>';

  return `<tr data-field-index="${analysisResult.field_index}">
    <th scope="row"><span class="field-name">${escapeHtml(presentation.client_field_name)}</span><span class="status ${statusClass(analysisResult.status)}">${escapeHtml(presentation.status_text)}</span></th>
    <td class="field-value">${escapeHtml(value)}</td>
    <td class="field-sources">${sourceHtml}</td>
  </tr>`;
}

function renderAttentionItem(field) {
  const { analysis_result: analysisResult, presentation, sources } = field;
  const sourceHtml = sources.length > 0
    ? `<ul class="sources">${sources.map(renderSource).join('')}</ul>`
    : '<span class="source-empty">—</span>';
